window.addEventListener('online',()=>{if(!editor)render();else{const badge=document.querySelector('#sync-status');if(badge)badge.outerHTML=syncBadge();}syncAccount({refresh:true}).catch(()=>{});if(user&&!editor&&!busy)processQueue().catch(e=>notify(e.message));});window.addEventListener('offline',()=>{const badge=document.querySelector('#sync-status');if(badge)badge.outerHTML=syncBadge();});setInterval(()=>{if(user&&!demo&&navigator.onLine)syncAccount().catch(()=>{});},30000);window.addEventListener('focus',()=>{if(user&&!demo)syncAccount({refresh:true}).catch(()=>{});});
if(sessionStorage.getItem('tooltrace-demo')==='1'){demo=true;activate({uid:'demo',email:'Mi archivo local',emailVerified:true},true);}
