document.addEventListener('submit',async e=>{if(e.target.getAttribute('id')!=='project-form')return;e.preventDefault();if(busy)return;busy=true;const form=e.target;const button=form.querySelector('button.primary');button.disabled=true;try{const entry=await projectDirectory.create(new FormData(form).get('name'));projects.push(entry);await openProject(entry.id);notify('Proyecto creado. Ya puedes cargar sus archivos.');}catch(error){busy=false;button.disabled=false;notify(error.message);render();}});

document.addEventListener('submit',async e=>{
 if(!['tool-form','group-form','delete-tool-form','delete-group-form','assign-serials-form','empty-group-form'].includes(e.target.getAttribute('id')))return;e.preventDefault();if(busy)return;const form=e.target,button=form.querySelector('button.primary');if(form.getAttribute('id')==='group-form'&&!validColorPicker(form))return;if(form.getAttribute('id')==='tool-form'&&form.querySelector('#inline-group').open&&form.querySelector('[data-inline-group-name]').value.trim()){form.querySelector('[data-inline-group-error]').textContent='Crea el grupo o cancela antes de guardar la herramienta.';form.querySelector('[data-inline-group-name]').focus();return;}busy=true;button.disabled=true;
 try{await pendingWrite;const values=Object.fromEntries(new FormData(form));
  if(form.getAttribute('id')==='group-form'){if(values.id)await repo.updateGroup(values);else await repo.saveGroup(values);await refreshData();notify(values.id?'Grupo actualizado.':'Grupo creado.');}
  else if(form.getAttribute('id')==='delete-group-form'){if(values.phrase!=='ELIMINAR')throw new Error('Confirma la eliminación.');await repo.deleteGroup(values.groupId,values.targetId);groupFilter=values.targetId;await refreshData();notify('Grupo eliminado. Seriales trasladados.');}
  else if(form.getAttribute('id')==='assign-serials-form'){const result=await repo.assignSerials(values);groupFilter=values.groupId;detail='';reportId='';await refreshData();notify(`${result.serials.length} serial(es) añadido(s) al grupo.`);}
  else if(form.getAttribute('id')==='empty-group-form'){if(values.phrase!=='ELIMINAR'||!pendingGroupEmpty||pendingGroupEmpty.scope!==owner())throw new Error('Vuelve a confirmar los seriales del grupo.');const result=await repo.deleteGroupTools(pendingGroupEmpty.id,{snapshot:pendingGroupEmpty.snapshot});await updateArchiveAfterToolRemoval(result,result.serials);pendingGroupEmpty=null;detail='';reportId='';await refreshData();notify('Seriales eliminados. El grupo se conserva vacío.');}
  else if(form.getAttribute('id')==='tool-form'){await repo.saveTool(values);await refreshData();notify('Herramienta guardada.');}
  else {if(values.phrase!=='ELIMINAR'||!pendingToolDelete||pendingToolDelete.scope!==owner())throw new Error('Abre de nuevo la confirmación de eliminación.');const {serial,snapshot}=pendingToolDelete,result=await repo.deleteTool(serial,{snapshot});
   await updateArchiveAfterToolRemoval(result,[serial]);
   pendingToolDelete=null;detail='';reportId='';await refreshData();notify('Herramienta eliminada. Los demás seriales se conservan.');}
  if(form.closest('dialog')?.dataset.returnToGroups){openModal(groupManager(data));document.querySelector('dialog').dataset.groupManager='true';}else document.querySelector('dialog')?.close();
 }catch(error){form.querySelector(':scope > [role=alert]').textContent=error.message;}finally{busy=false;button.disabled=false;render();}
});

async function updateArchiveAfterToolRemoval(result,serials){
for(const entry of inbox){if(result.removedDocumentIds.includes(entry.id)){entry.deletedByTool=serials[0];await persist(entry);}else if(result.affectedDocumentIds.includes(entry.id)&&entry.editingDraft){entry.editingDraft.records=entry.editingDraft.records.filter(r=>!serials.includes(serialNormalizer(r.serial)));entry.editingDraft.countConfirmation=null;const current=(await repo.load()).documents.find(d=>d.id===entry.id);if(current){entry.editingDraft.baseRevision=current.revision;entry.editingDraft.createdAt=current.createdAt;}await persist(entry);}}

}

async function createInlineGroup(form){
 if(!form||busy)return;if(!validColorPicker(form.querySelector('#inline-group')))return;
 const name=form.querySelector('[data-inline-group-name]'),color=form.querySelector('[data-inline-group-color]'),error=form.querySelector('[data-inline-group-error]'),status=form.querySelector('[data-inline-group-status]');
 error.textContent='';status.textContent='';if(!name.value.trim()){error.textContent='Escribe el nombre del nuevo grupo.';name.focus();return;}
 busy=true;const controls=[...form.querySelectorAll('button,input,select')],disabled=controls.map(c=>c.disabled);controls.forEach(c=>c.disabled=true);
 try{await pendingWrite;const entry=await repo.saveGroup({name:name.value,color:color.value});await refreshData();const select=form.elements.groupId;select.replaceChildren(...groups(data).map(g=>new Option(g.name,g.id)));select.value=entry.id;name.value='';form.querySelector('#inline-group').open=false;status.textContent='Grupo seleccionado: '+entry.name+'.';}
 catch(e){error.textContent=e.message;}
 finally{busy=false;controls.forEach((c,i)=>c.disabled=disabled[i]);if(error.textContent)name.focus();else form.elements.groupId.focus();}
}

