function toolSelectionBar(list){const available=new Set(data.tools.map(t=>t.serial));for(const serial of selectedTools)if(!available.has(serial))selectedTools.delete(serial);const n=selectedTools.size,all=list.length>0&&list.every(t=>selectedTools.has(t.serial));return '<div class="tool-selection-bar '+(n?'has-selection':'')+'"><label><input id="tool-select-all" type="checkbox" '+(all?'checked':'')+' '+(!list.length?'disabled':'')+'>Seleccionar todas'+(activeToolFilters()?' las filtradas':'')+'</label><span role="status" aria-live="polite">'+n+' '+(n===1?'seleccionada':'seleccionadas')+'</span><div class="row-actions"><button class="primary" data-action="bulk-group" '+(!n?'disabled':'')+'>Asignar grupo</button>'+(n?'<button class="subtle" data-action="clear-tool-selection">Limpiar selección</button>':'')+'</div></div>';}
function updateToolSelection(){const bar=document.querySelector('#tool-selection-bar');if(!bar)return;const list=filteredTools();bar.innerHTML=toolSelectionBar(list);const count=list.filter(t=>selectedTools.has(t.serial)).length,all=document.querySelector('#tool-select-all');all.indeterminate=count>0&&count<list.length;}
document.addEventListener('submit',async e=>{
 if(e.target.getAttribute('id')!=='bulk-group-form')return;e.preventDefault();if(busy)return;const form=e.target,error=form.querySelector('[data-bulk-error]');error.textContent='';if(bulkScope!==owner()){error.textContent='El proyecto cambió. Vuelve a seleccionar las herramientas.';return;}
 if(form.querySelector('#inline-group').open&&form.querySelector('[data-inline-group-name]').value.trim()){error.textContent='Crea el grupo antes de asignarlo.';return;}
 busy=true;const controls=[...form.querySelectorAll('button,input,select')],disabled=controls.map(c=>c.disabled);controls.forEach(c=>c.disabled=true);
 try{await pendingWrite;const target=form.elements.groupId.value;for(let i=0;i<bulkSerials.length;i+=100){const batch=bulkSerials.slice(i,i+100);await repo.assignSerials({groupId:target,serials:batch.map(t=>t.serial),requireExisting:true,createdAtBySerial:Object.fromEntries(batch.map(t=>[t.serial,t.createdAt]))});for(const t of batch)selectedTools.delete(t.serial);}await refreshData();document.querySelector('dialog')?.close();notify('Grupo asignado.');}
 catch(err){error.textContent=err.message;await refreshData();bulkSerials=bulkSerials.filter(t=>selectedTools.has(t.serial));}
 finally{busy=false;controls.forEach((c,i)=>c.disabled=disabled[i]);render();}
});
